  "website.main.guidelines.eyebrow": "House rules",
  "website.main.guidelines.heading": "Community Guidelines",
  "website.main.guidelines.intro": "Short, sweet, and meant to keep Duncit a place worth being.",
  "website.main.guidelines.rule1Heading": "1. Be kind",
  "website.main.guidelines.rule1Text": "Treat people the way you'd want to be treated on your worst Monday. Hate, harassment, or threats of any kind earn an instant exit.",
  "website.main.guidelines.rule2Heading": "2. Be real",
  "website.main.guidelines.rule2Text": "Use a real photo and a name people can call you. Catfishing, impersonation, and bots are removed on sight.",
  "website.main.guidelines.rule3Heading": "3. Keep it safe",
  "website.main.guidelines.rule3Text": "No nudity, no doxxing, no sharing private info without consent. If a chat feels off, hit the report button — a human will respond.",
  "website.main.guidelines.rule4Heading": "4. Don't sell, don't spam",
  "website.main.guidelines.rule4Text": "Duncit isn't a marketplace or an MLM funnel. Promo links and recruitment messages get filtered.",
  "website.main.guidelines.rule5Heading": "5. Respect privacy",
  "website.main.guidelines.rule5Text": "What's shared in chat stays in chat. Screenshots without permission are not the move.",
  "website.main.guidelines.rule6Heading": "6. Use the tools",
  "website.main.guidelines.rule6Text": "Block, mute, and report exist for a reason. Use them freely — and we'll back you up.",
  "website.main.guidelines.title": "Community Guidelines",
  "website.main.guidelines.wrongHeading": "If something goes wrong",
  "website.main.guidelines.wrongText": "Reach out to",
  "website.main.guidelines.wrongTextAfter": "or use the in-app report flow. Our Trust & Safety team reviews every report, every time.",
  "website.main.help.askText": "Can't find it? Submit your question and we'll answer.",
